#include "sha256.h"
#include <stdio.h>
#include <string.h>
int main(){
  const char*msgs[]={"","abc","abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq","a"};
  for(int k=0;k<4;k++){
    epic_sha256_t c; uint8_t out[32];
    epic_sha256_init(&c);
    epic_sha256_update(&c,(const uint8_t*)msgs[k],strlen(msgs[k]));
    epic_sha256_final(&c,out);
    for(int i=0;i<32;i++)printf("%02x",out[i]);
    printf("\n");
  }
  /* long streaming test: 1000000 'a' via chunked updates */
  epic_sha256_t c; uint8_t out[32]; epic_sha256_init(&c);
  static char buf[1024]; memset(buf,'a',sizeof buf);
  for(int i=0;i<1000;i++) epic_sha256_update(&c,(uint8_t*)buf,sizeof buf);
  epic_sha256_final(&c,out);
  for(int i=0;i<32;i++)printf("%02x",out[i]);
  printf("\n");
  return 0;
}
EOF
